import 'package:flutter/material.dart';
import '../../accounts/presentation/accounts_page.dart';import '../../auth/data/auth_repository.dart';import '../../dashboard/presentation/dashboard_page.dart';import '../../profile/presentation/profile_page.dart';import 'shell_destination.dart';
class AppShell extends StatefulWidget{const AppShell({required this.repository,required this.accessToken,required this.email,required this.onLogout,super.key});final AuthRepository repository;final String accessToken,email;final Future<void> Function() onLogout;@override State<AppShell> createState()=>_AppShellState();}
class _AppShellState extends State<AppShell>{int index=0;late List<Widget> pages;@override void initState(){super.initState();pages=_pages();}@override void didUpdateWidget(covariant AppShell old){super.didUpdateWidget(old);if(old.accessToken!=widget.accessToken||old.email!=widget.email)pages=_pages();}List<Widget> _pages()=>[DashboardPage(key:const PageStorageKey('dashboard'),accessToken:widget.accessToken),AccountsPage(key:const PageStorageKey('accounts'),accessToken:widget.accessToken),const _P(key:PageStorageKey('credit'),title:'Credit',icon:Icons.credit_card_outlined),const _P(key:PageStorageKey('lending'),title:'Lending',icon:Icons.handshake_outlined),ProfilePage(key:const PageStorageKey('profile'),repository:widget.repository,initialEmail:widget.email,onLogout:widget.onLogout)];
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Money Maintainer'),actions:[if(index!=4)IconButton(onPressed:()=>setState(()=>index=4),icon:const Icon(Icons.person_outline))]),body:IndexedStack(index:index,children:pages),bottomNavigationBar:NavigationBar(selectedIndex:index,onDestinationSelected:(i)=>setState(()=>index=i),destinations:ShellDestination.values.map((d)=>NavigationDestination(icon:Icon(d.icon),selectedIcon:Icon(d.selectedIcon),label:d.label)).toList(growable:false)));}
class _P extends StatelessWidget{const _P({required this.title,required this.icon,super.key});final String title;final IconData icon;@override Widget build(BuildContext c)=>Center(child:Column(mainAxisSize:MainAxisSize.min,children:[Icon(icon,size:48),const SizedBox(height:12),Text(title,style:Theme.of(c).textTheme.headlineSmall)]));}
